1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"syscall"
14	)
15	
16	// Block is one validated, deduplicated input block. Swaps are kept in
17	// canonical order: exact duplicates removed, sorted by Index.
18	type Block struct {
19		ChainID     string
20		BlockHash   string
21		BlockNumber int64
22		Swaps       []Swap
23	}
24	
25	// ReportFinding is one risk conclusion inside a block report. Evidence
26	// carries the raw fields of every swap that participated in the judgment.
27	type ReportFinding struct {
28		Kind     string `json:"kind"`
29		Severity int    `json:"severity"`
30		TxHash   string `json:"txHash"`
31		Evidence []Swap `json:"evidence"`
32	}
33	
34	// Report is the archived per-block risk report. Version records the full
35	// rule parameters that produced the findings, so the report stays
36	// interpretable without the original rule definition.
37	type Report struct {
38		ChainID     string          `json:"chainId"`
39		BlockHash   string          `json:"blockHash"`
40		BlockNumber int64           `json:"blockNumber"`
41		SwapCount   int             `json:"swapCount"`
42		Version     RuleVersion     `json:"version"`
43		Findings    []ReportFinding `json:"findings"`
44	}
45	
46	// LineError pins a replay failure to a 1-based input line.
47	type LineError struct {
48		Line int
49		Err  error
50	}
51	
52	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
53	func (e *LineError) Unwrap() error { return e.Err }
54	
55	// ErrBusy reports an archive locked by another process.
56	var ErrBusy = errors.New("archive is busy")
57	
58	// ErrUnknownBlock reports a query for a block that was never archived.
59	var ErrUnknownBlock = errors.New("unknown block")
60	
61	type blockID struct {
62		chainID   string
63		blockHash string
64	}
65	
66	// swapLine mirrors one swap record inside a block line. Pointers
67	// distinguish a missing field (or an explicit null) from an explicit
68	// zero value: a replay record must be complete on its own, so In, Out,
69	// GasPrice and Index are all required and may not be null.
70	type swapLine struct {
71		TxHash   *string `json:"TxHash"`
72		Pool     *string `json:"Pool"`
73		Trader   *string `json:"Trader"`
74		In       *int64  `json:"In"`
75		Out      *int64  `json:"Out"`
76		GasPrice *int64  `json:"GasPrice"`
77		Index    *int    `json:"Index"`
78	}
79	
80	// blockLine mirrors one input line. Pointers distinguish a missing field
81	// from an explicit zero value.
82	type blockLine struct {
83		ChainID     *string     `json:"chainId"`
84		BlockHash   *string     `json:"blockHash"`
85		BlockNumber *int64      `json:"blockNumber"`
86		Swaps       *[]swapLine `json:"swaps"`
87	}
88	
89	func parseBlock(text string) (Block, error) {
90		var raw blockLine
91		dec := json.NewDecoder(strings.NewReader(text))
92		if err := dec.Decode(&raw); err != nil {
93			return Block{}, fmt.Errorf("invalid JSON: %w", err)
94		}
95		if err := blockTrailingData(text, int(dec.InputOffset())); err != nil {
96			return Block{}, err
97		}
98		if raw.ChainID == nil || *raw.ChainID == "" {
99			return Block{}, errors.New("chainId must be a non-empty string")
100		}
101		if raw.BlockHash == nil || *raw.BlockHash == "" {
102			return Block{}, errors.New("blockHash must be a non-empty string")
103		}
104		if raw.BlockNumber == nil {
105			return Block{}, errors.New("blockNumber is required")
106		}
107		if *raw.BlockNumber < 0 {
108			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
109		}
110		if raw.Swaps == nil {
111			return Block{}, errors.New("swaps must be an array")
112		}
113	
114		byTx := make(map[string]Swap)
115		byIndex := make(map[int]string)
116		swaps := []Swap{}
117		for i, s := range *raw.Swaps {
118			if s.TxHash == nil || *s.TxHash == "" {
119				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
120			}
121			if s.Pool == nil || *s.Pool == "" {
122				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
123			}
124			if s.Trader == nil || *s.Trader == "" {
125				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
126			}
127			// Every numeric field must be present and non-null in this very
128			// record; an explicit zero is a valid value, never a missing one.
129			// Values must not be borrowed from a neighbour, a same-hash record
130			// or a default, so an incomplete record is rejected before dedup
131			// even when a complete record with the same tx hash exists.
132			for _, f := range []struct {
133				name string
134				v    *int64
135			}{
136				{"In", s.In}, {"Out", s.Out}, {"GasPrice", s.GasPrice},
137			} {
138				if f.v == nil {
139					return Block{}, fmt.Errorf("swaps[%d]: %s is required and must not be null", i, f.name)
140				}
141			}
142			if s.Index == nil {
143				return Block{}, fmt.Errorf("swaps[%d]: Index is required and must not be null", i)
144			}
145			in, out, gasPrice, index := *s.In, *s.Out, *s.GasPrice, *s.Index
146			if in < 0 || out < 0 || gasPrice < 0 || index < 0 {
147				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
148			}
149			swap := Swap{
150				TxHash: *s.TxHash, Pool: *s.Pool, Trader: *s.Trader,
151				In: in, Out: out, GasPrice: gasPrice, Index: index,
152			}
153			if prev, ok := byTx[swap.TxHash]; ok {
154				if prev != swap {
155					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, swap.TxHash)
156				}
157				continue // exact duplicate, keep one copy
158			}
159			if other, ok := byIndex[swap.Index]; ok {
160				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, swap.Index, other)
161			}
162			byTx[swap.TxHash] = swap
163			byIndex[swap.Index] = swap.TxHash
164			swaps = append(swaps, swap)
165		}
166		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
167		return Block{
168			ChainID:     *raw.ChainID,
169			BlockHash:   *raw.BlockHash,
170			BlockNumber: *raw.BlockNumber,
171			Swaps:       swaps,
172		}, nil
173	}
174	
175	// blockTrailingData names the first non-whitespace byte after the block
176	// object on a replay line, so an unmatched '}' or ']' — or a second value
177	// of any kind — is reported directly; only whitespace may follow the
178	// object. dec.More cannot see this: after a complete top-level value it
179	// only looks for the start of another value and treats stray closing
180	// brackets as "nothing more".
181	func blockTrailingData(text string, offset int) error {
182		rest := strings.TrimLeft(text[offset:], " \t\n\r")
183		if len(rest) > 0 {
184			return fmt.Errorf("invalid JSON: unexpected trailing data after block object: %s", trailingTokenName(rest[0]))
185		}
186		return nil
187	}
188	
189	func swapsEqual(a, b []Swap) bool {
190		if len(a) != len(b) {
191			return false
192		}
193		for i := range a {
194			if a[i] != b[i] {
195				return false
196			}
197		}
198		return true
199	}
200	
201	// sameContent reports whether two blocks carry the same content. Both sides
202	// are canonical (deduplicated, sorted by Index), so ordering and exact
203	// duplicates in the input do not affect the comparison.
204	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
205		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
206	}
207	
208	// DetectBlock checks every swap against its adjacent neighbours within its
209	// pool under the built-in rules. See DetectBlockWithRules.
210	func DetectBlock(swaps []Swap) []ReportFinding {
211		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
212	}
213	
214	// DetectBlockWithRules checks every swap against its adjacent neighbours
215	// within its pool under the given rule version: a sandwich when the same
216	// trader brackets the victim with higher gas on both sides, otherwise a
217	// displacement when the previous swap's gas strictly exceeds the configured
218	// multiple of the victim's. The last swap of a pool is checked too. An
219	// enabled sandwich takes priority over displacement for the same victim;
220	// with the sandwich rule off the victim can still be flagged for
221	// displacement. With both rules off the result is an empty slice. The
222	// judgment itself is shared with Detect; this entry only adds the block
223	// report's raw-swap evidence and ordering.
224	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
225		pools := make(map[string][]Swap)
226		for _, s := range swaps {
227			pools[s.Pool] = append(pools[s.Pool], s)
228		}
229		findings := []ReportFinding{}
230		for _, pool := range pools {
231			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
232			for i, victim := range pool {
233				var front, back *Swap
234				if i > 0 {
235					front = &pool[i-1]
236				}
237				if i+1 < len(pool) {
238					back = &pool[i+1]
239				}
240				j, hit := judgeVictim(front, victim, back, rules)
241				if !hit {
242					continue
243				}
244				// The evidence keeps the full swap fields of every record that
245				// participated: front, victim, and for a sandwich also back.
246				evidence := []Swap{*front, victim}
247				if j.kind == "sandwich" {
248					evidence = append(evidence, *back)
249				}
250				findings = append(findings, ReportFinding{
251					Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
252					Evidence: evidence,
253				})
254			}
255		}
256		sort.Slice(findings, func(i, j int) bool {
257			if findings[i].Severity != findings[j].Severity {
258				return findings[i].Severity > findings[j].Severity
259			}
260			return findings[i].TxHash < findings[j].TxHash
261		})
262		return findings
263	}
264	
265	// record is the archived form of a block: the report plus the canonical
266	// swaps, so a later import can detect content conflicts. Version carries
267	// the full rule parameters used for the findings; it is nil only in
268	// archives written before rule versions existed, which are interpreted
269	// under the built-in rules.
270	type record struct {
271		ChainID     string          `json:"chainId"`
272		BlockHash   string          `json:"blockHash"`
273		BlockNumber int64           `json:"blockNumber"`
274		Swaps       []Swap          `json:"swaps"`
275		Findings    []ReportFinding `json:"findings"`
276		Version     *RuleVersion    `json:"version,omitempty"`
277	}
278	
279	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
280	
281	func (r record) ruleVersion() RuleVersion {
282		if r.Version != nil {
283			return *r.Version
284		}
285		return BuiltinVersion()
286	}
287	
288	func (r record) report() Report {
289		return Report{
290			ChainID:     r.ChainID,
291			BlockHash:   r.BlockHash,
292			BlockNumber: r.BlockNumber,
293			SwapCount:   len(r.Swaps),
294			Version:     r.ruleVersion(),
295			Findings:    r.Findings,
296		}
297	}
298	
299	const (
300		archiveFileName = "archive.json"
301		lockFileName    = "lock"
302	)
303	
304	type archiveData struct {
305		Records []record `json:"records"`
306		// Versions and EnabledVersion are absent in archives written before
307		// rule versions existed; such archives run the built-in rules.
308		Versions       []RuleVersion `json:"versions,omitempty"`
309		EnabledVersion string        `json:"enabledVersion,omitempty"`
310		// Suppressions and AlertRecords are absent in archives written before
311		// offline alerting existed; such archives simply have no registered
312		// conditions and no processing history.
313		Suppressions []Suppression      `json:"suppressions,omitempty"`
314		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
315		// Reviews is absent in archives written before manual reviews existed;
316		// every conclusion then behaves as unreviewed.
317		Reviews []ReviewObject `json:"reviews,omitempty"`
318	}
319	
320	// readArchiveBytes returns the exact bytes of the archive file, or nil
321	// when no archive exists yet.
322	func readArchiveBytes(dir string) ([]byte, error) {
323		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
324		if errors.Is(err, os.ErrNotExist) {
325			return nil, nil
326		}
327		if err != nil {
328			return nil, err
329		}
330		return raw, nil
331	}
332	
333	func readArchive(dir string) (archiveData, error) {
334		raw, err := readArchiveBytes(dir)
335		if err != nil {
336			return archiveData{}, err
337		}
338		if raw == nil {
339			return archiveData{Records: []record{}}, nil
340		}
341		var data archiveData
342		if err := json.Unmarshal(raw, &data); err != nil {
343			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
344		}
345		return data, nil
346	}
347	
348	// replayArchiveDoc mirrors the archive file the way a replay reads and
349	// writes it: records, suppressions, alert records and reviews are fully
350	// decoded, but each registered version is kept as its raw stored document.
351	// A corrupt version entry — a wrong-typed field, say — then cannot break
352	// the read or masquerade as whole-archive corruption; the version this run
353	// selects is judged on its own by intactVersion, and entries the run does
354	// not select are written back byte for byte: a replay never repairs,
355	// completes or drops a stored version, not even a corrupt one.
356	type replayArchiveDoc struct {
357		Records        []record           `json:"records"`
358		Versions       []json.RawMessage  `json:"versions,omitempty"`
359		EnabledVersion string             `json:"enabledVersion,omitempty"`
360		Suppressions   []Suppression      `json:"suppressions,omitempty"`
361		AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
362		Reviews        []ReviewObject     `json:"reviews,omitempty"`
363	}
364	
365	// writeArchiveAtomic replaces the archive file in one rename, so a crash
366	// can only expose the previous or the next complete commit, never a half
367	// written file.
368	func writeArchiveAtomic(dir string, data any) error {
369		raw, err := json.MarshalIndent(data, "", "  ")
370		if err != nil {
371			return err
372		}
373		tmp := filepath.Join(dir, archiveFileName+".tmp")
374		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
375		if err != nil {
376			return err
377		}
378		if _, err := f.Write(raw); err != nil {
379			f.Close()
380			os.Remove(tmp)
381			return err
382		}
383		if err := f.Sync(); err != nil {
384			f.Close()
385			os.Remove(tmp)
386			return err
387		}
388		if err := f.Close(); err != nil {
389			os.Remove(tmp)
390			return err
391		}
392		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
393			os.Remove(tmp)
394			return err
395		}
396		if d, err := os.Open(dir); err == nil {
397			d.Sync()
398			d.Close()
399		}
400		return nil
401	}
402	
403	// lockArchive takes an flock on the archive's lock file. The lock is
404	// released automatically if the process dies, so no stale locks survive.
405	func lockArchive(dir string, how int) (*os.File, error) {
406		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
407		if err != nil {
408			return nil, err
409		}
410		if err := syscall.Flock(int(f.Fd()), how); err != nil {
411			f.Close()
412			if errors.Is(err, syscall.EWOULDBLOCK) {
413				return nil, ErrBusy
414			}
415			return nil, err
416		}
417		return f, nil
418	}
419	
420	type parsedBlock struct {
421		line  int
422		block Block
423	}
424	
425	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
426		var out []parsedBlock
427		reader := bufio.NewReader(r)
428		lineNo := 0
429		for {
430			raw, err := reader.ReadBytes('\n')
431			if len(raw) > 0 {
432				lineNo++
433			}
434			if text := strings.TrimSpace(string(raw)); text != "" {
435				block, perr := parseBlock(text)
436				if perr != nil {
437					return nil, &LineError{Line: lineNo, Err: perr}
438				}
439				out = append(out, parsedBlock{line: lineNo, block: block})
440			}
441			if err == io.EOF {
442				return out, nil
443			}
444			if err != nil {
445				return nil, err
446			}
447		}
448	}
449	
450	// ReplayFile imports the line-delimited blocks in inputPath into the
451	// archive at dir and returns one report per distinct block, in order of
452	// first appearance. New blocks are judged under the archive's currently
453	// enabled rule version; that version's stored document must still satisfy
454	// the registration rules in full, or the whole replay fails with
455	// ErrCorruptVersion before any report is produced.
456	func ReplayFile(inputPath, dir string) ([]Report, error) {
457		return replayFile(inputPath, dir, "")
458	}
459	
460	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
461	// version instead of the archive's enabled one. The named version's stored
462	// document must still satisfy the registration rules in full; a corrupt
463	// one fails the whole replay with ErrCorruptVersion rather than judging
464	// under zeroed or substituted parameters.
465	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
466		if versionID == "" {
467			return nil, errors.New("version id must not be empty")
468		}
469		return replayFile(inputPath, dir, versionID)
470	}
471	
472	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
473		f, err := os.Open(inputPath)
474		if err != nil {
475			return nil, err
476		}
477		defer f.Close()
478		return doReplay(f, dir, versionID)
479	}
480	
481	// Replay parses, validates and archives blocks from r under the archive's
482	// currently enabled rule version. Every line is checked before anything is
483	// written; any failure leaves the archive untouched. New reports are
484	// committed together in a single atomic write. The selected version's
485	// stored document is re-validated before any block is judged: a corrupt
486	// version fails the whole replay with ErrCorruptVersion — never a
487	// substituted or zeroed parameter set — even when no input block would
488	// have triggered the damaged rule.
489	func Replay(input io.Reader, dir string) ([]Report, error) {
490		return doReplay(input, dir, "")
491	}
492	
493	// ReplayWithVersion is Replay under an explicitly registered rule version
494	// instead of the archive's enabled one, with the same integrity check: a
495	// corrupt stored version document fails the whole replay with
496	// ErrCorruptVersion before any report is produced.
497	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
498		if versionID == "" {
499			return nil, errors.New("version id must not be empty")
500		}
501		return doReplay(input, dir, versionID)
502	}
503	
504	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
505		parsed, err := parseBlocks(input)
506		if err != nil {
507			return nil, err
508		}
509	
510		// Collapse repeated identities within this file, keeping first
511		// appearance order; conflicting content rejects the whole file.
512		type occurrence struct {
513			block Block
514			line  int
515		}
516		order := []occurrence{}
517		firstSeen := make(map[blockID]int)
518		for _, p := range parsed {
519			id := blockID{p.block.ChainID, p.block.BlockHash}
520			if first, ok := firstSeen[id]; ok {
521				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
522					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
523						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
524				}
525				continue
526			}
527			firstSeen[id] = len(order)
528			order = append(order, occurrence{block: p.block, line: p.line})
529		}
530	
531		if err := os.MkdirAll(dir, 0o755); err != nil {
532			return nil, err
533		}
534		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
535		if err != nil {
536			return nil, err
537		}
538		defer lock.Close()
539	
540		// Decode with each registered version kept as its raw stored document,
541		// so a wrong-typed field in one version is that version's corruption,
542		// not whole-archive corruption, and the selected version's document can
543		// be re-validated from its bytes the same way a single-block comparison
544		// proves its version intact.
545		raw, err := readArchiveBytes(dir)
546		if err != nil {
547			return nil, err
548		}
549		data := replayArchiveDoc{Records: []record{}}
550		if raw != nil {
551			if err := json.Unmarshal(raw, &data); err != nil {
552				return nil, fmt.Errorf("archive is corrupted: %w", err)
553			}
554		}
555		// Resolve the version once, while the exclusive lock is held: every
556		// new block in this run is judged under the same rules even if another
557		// process enables a different version right after we finish. The
558		// selected version's stored document must still satisfy the
559		// registration rules in full; a corrupt one fails the whole replay
560		// with ErrCorruptVersion here, before any block is judged, any report
561		// is produced or anything is written — even when the input is empty,
562		// holds only blocks already archived, or would never trigger the
563		// damaged rule. The corrupt content is never replaced by the enabled
564		// version, the built-in rules or defaults.
565		version, err := resolveReplayVersion(data, versionID)
566		if err != nil {
567			return nil, err
568		}
569		archived := make(map[blockID]int, len(data.Records))
570		for i, rec := range data.Records {
571			archived[rec.id()] = i
572		}
573	
574		reports := make([]Report, 0, len(order))
575		changed := false
576		for _, occ := range order {
577			id := blockID{occ.block.ChainID, occ.block.BlockHash}
578			if idx, ok := archived[id]; ok {
579				rec := data.Records[idx]
580				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
581					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
582						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
583				}
584				// Identical re-import: return the original report, add nothing.
585				reports = append(reports, rec.report())
586				continue
587			}
588			rec := record{
589				ChainID:     occ.block.ChainID,
590				BlockHash:   occ.block.BlockHash,
591				BlockNumber: occ.block.BlockNumber,
592				Swaps:       occ.block.Swaps,
593				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
594				Version:     &version,
595			}
596			archived[id] = len(data.Records)
597			data.Records = append(data.Records, rec)
598			reports = append(reports, rec.report())
599			changed = true
600		}
601		if changed {
602			if err := writeArchiveAtomic(dir, data); err != nil {
603				return nil, err
604			}
605		}
606		return reports, nil
607	}
608	
609	// resolveReplayVersion picks the rule version for one replay run — the
610	// explicitly requested one, or the archive's currently enabled version —
611	// and proves its stored archive document still satisfies every
612	// registration rule, re-validating the raw document with the same parser
613	// registrations pass. The decoded struct cannot do this: a missing
614	// enabled, severity or multiplier field unmarshals as the zero value and
615	// is indistinguishable from an explicitly declared one, and a zero
616	// displacement multiplier even crashes detection. An explicitly declared
617	// false or any in-range value is valid; a missing or null field, a wrong
618	// type or an out-of-range number makes the version corrupt, and the
619	// failure names the version and the offending rule or field. Archives
620	// written before rule versions existed have no enabled marker and run the
621	// built-in rules; the built-in version is constructed in code and always
622	// intact.
623	func resolveReplayVersion(data replayArchiveDoc, versionID string) (RuleVersion, error) {
624		id := versionID
625		if id == "" {
626			id = data.EnabledVersion
627			if id == "" {
628				return BuiltinVersion(), nil
629			}
630		}
631		return intactVersion(data.Versions, id)
632	}
633	
634	// Query returns the archived report for one block identity. It only reads
635	// the archive; the original input file is not needed.
636	func Query(dir, chainID, blockHash string) (Report, error) {
637		if _, err := os.Stat(dir); err != nil {
638			if errors.Is(err, os.ErrNotExist) {
639				return Report{}, ErrUnknownBlock
640			}
641			return Report{}, err
642		}
643		lock, err := lockArchive(dir, syscall.LOCK_SH)
644		if err != nil {
645			return Report{}, err
646		}
647		defer lock.Close()
648	
649		data, err := readArchive(dir)
650		if err != nil {
651			return Report{}, err
652		}
653		for _, rec := range data.Records {
654			if rec.ChainID == chainID && rec.BlockHash == blockHash {
655				return rec.report(), nil
656			}
657		}
658		return Report{}, ErrUnknownBlock
659	}
