		if err != nil {
			fmt.Fprintf(os.Stderr, "rules show: %v\n", err)
			os.Exit(1)
		}
		writeJSON(version)
	case "register":
		if len(args) != 3 {
			fmt.Fprintln(os.Stderr, "usage: mevwatch rules register <archive-dir> <spec-file>")
			os.Exit(2)
		}
		var raw []byte
		var err error
		if args[2] == "-" {
			raw, err = io.ReadAll(os.Stdin)
