1	package mevwatch
2	
3	// Regression coverage for replaying against a corrupt archived rule
4	// version. A replay must prove the version it selected — explicitly via
5	// --version or implicitly through the archive's enabled marker — still
6	// satisfies the registration rules in full before it produces any report,
7	// exactly the way a single-block comparison and a review-range evaluation
8	// already refuse such versions. The corrupt content is never replaced by
9	// the enabled version, the built-in rules or defaults; a corrupt version
10	// is never misreported as unknown; and a refused replay leaves the archive
11	// — reports, rules, the enabled marker, alert records and reviews — byte
12	// for byte untouched.
13	
14	import (
15		"encoding/json"
16		"errors"
17		"os"
18		"path/filepath"
19		"reflect"
20		"strings"
21		"testing"
22	)
23	
24	// replayCorruptInput is one new block whose adjacent same-pool swaps hit
25	// displacement under any intact multiplier — the input shape that crashed
26	// detection when a stored multiplier decayed to zero.
27	var replayCorruptInput = cmpBlockLine("1", "0xnew", 8,
28		cmpSwap("0xn1", "p1", "w", 40, 0),
29		cmpSwap("0xn2", "p1", "u", 10, 1),
30	)
31	
32	// readArchiveFile returns the archive file's exact bytes.
33	func readArchiveFile(t *testing.T, dir string) []byte {
34		t.Helper()
35		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
36		if err != nil {
37			t.Fatal(err)
38		}
39		return raw
40	}
41	
42	// TestReplayCorruptVersionRefused runs the full corruption matrix against
43	// an explicitly named replay version: every way a stored version document
44	// can stop satisfying the registration rules must fail the whole replay
45	// with ErrCorruptVersion before any report is produced.
46	func TestReplayCorruptVersionRefused(t *testing.T) {
47		for _, tc := range corruptVersionCases {
48			t.Run(tc.name, func(t *testing.T) {
49				dir := setupCorruptCompareArchive(t)
50				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
51					tc.mutate(t, ver)
52				})
53				before := readArchiveFile(t, dir)
54	
55				reports, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC")
56				if err == nil {
57					t.Fatalf("corrupt version replayed successfully: %+v", reports)
58				}
59				if !errors.Is(err, ErrCorruptVersion) {
60					t.Fatalf("error = %v, want ErrCorruptVersion", err)
61				}
62				if errors.Is(err, ErrUnknownVersion) {
63					t.Fatalf("corruption misreported as unknown version: %v", err)
64				}
65				if !strings.Contains(err.Error(), "candC") {
66					t.Fatalf("error must name the selected version, got %v", err)
67				}
68				if !strings.Contains(err.Error(), tc.wantErr) {
69					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
70				}
71				if reports != nil {
72					t.Fatalf("a refused replay must return no reports, got %+v", reports)
73				}
74				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
75					t.Fatalf("refused replay changed the archive")
76				}
77			})
78		}
79	}
80	
81	// TestReplayCorruptEnabledVersionRefused runs the same matrix against the
82	// archive's enabled version: a plain replay without --version selects it
83	// and must refuse it just the same. The version is enabled before the
84	// stored document is damaged.
85	func TestReplayCorruptEnabledVersionRefused(t *testing.T) {
86		for _, tc := range corruptVersionCases {
87			t.Run(tc.name, func(t *testing.T) {
88				dir := setupCorruptCompareArchive(t)
89				if _, err := EnableVersion(dir, "candC"); err != nil {
90					t.Fatalf("EnableVersion: %v", err)
91				}
92				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
93					tc.mutate(t, ver)
94				})
95				before := readArchiveFile(t, dir)
96	
97				// Blank-lines-only input: the refusal is decided by the selected
98				// version, never by whether any input block triggers the rule.
99				_, err := Replay(strings.NewReader("\n  \n"), dir)
100				if !errors.Is(err, ErrCorruptVersion) {
101					t.Fatalf("error = %v, want ErrCorruptVersion", err)
102				}
103				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), tc.wantErr) {
104					t.Fatalf("error must name version candC and field %q, got %v", tc.wantErr, err)
105				}
106				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
107					t.Fatalf("refused replay changed the archive")
108				}
109			})
110		}
111	}
112	
113	// TestReplayCorruptVersionInputShapes proves the refusal is independent of
114	// the input: an empty-swaps block, a block already archived with identical
115	// content, and a file holding only blank lines all fail the same way, and
116	// a batch mixing an already archived block with a new one produces no
117	// partial success — no report for the old block, no archived new block.
118	func TestReplayCorruptVersionInputShapes(t *testing.T) {
119		archivedLine := cmpBlockLine("1", "0xblk", 7,
120			cmpSwap("0xf", "p1", "w", 40, 0),
121			cmpSwap("0xv", "p1", "u", 10, 1),
122		)
123		cases := []struct {
124			name  string
125			input string
126		}{
127			{"empty swaps block", `{"chainId":"1","blockHash":"0xempty","blockNumber":3,"swaps":[]}`},
128			{"identical archived block", archivedLine},
129			{"blank lines only", "\n   \n\t\n"},
130			{"archived block then new block", archivedLine + "\n" + replayCorruptInput},
131			{"new block then archived block", replayCorruptInput + "\n" + archivedLine},
132		}
133		for _, tc := range cases {
134			t.Run(tc.name, func(t *testing.T) {
135				dir := setupCorruptCompareArchive(t)
136				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
137					delete(storedRule(t, ver, "displacement"), "multiplier")
138				})
139				before := readArchiveFile(t, dir)
140	
141				reports, err := ReplayWithVersion(strings.NewReader(tc.input), dir, "candC")
142				if !errors.Is(err, ErrCorruptVersion) {
143					t.Fatalf("error = %v, want ErrCorruptVersion", err)
144				}
145				if reports != nil {
146					t.Fatalf("partial success leaked reports: %+v", reports)
147				}
148				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
149					t.Fatalf("refused replay changed the archive")
150				}
151				// The new block from the mixed batches was never archived.
152				if _, err := Query(dir, "1", "0xnew"); !errors.Is(err, ErrUnknownBlock) {
153					t.Fatalf("new block archived by a refused replay: %v", err)
154				}
155			})
156		}
157	}
158	
159	// TestReplayCorruptVersionDistinctFromUnknown pins the boundary: a version
160	// that was never registered stays an unknown-version failure, a corrupt
161	// registered version is never misreported as unknown, and a corrupt
162	// sibling blocks neither an explicitly named intact version nor the
163	// enabled one.
164	func TestReplayCorruptVersionDistinctFromUnknown(t *testing.T) {
165		dir := setupCorruptCompareArchive(t)
166		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
167			delete(storedRule(t, ver, "displacement"), "multiplier")
168		})
169	
170		if _, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "ghost"); !errors.Is(err, ErrUnknownVersion) ||
171			errors.Is(err, ErrCorruptVersion) {
172			t.Fatalf("unknown version error = %v", err)
173		}
174	
175		// An explicit replay under the intact twin succeeds against the same
176		// archive and judges under twin's parameters.
177		reports, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "twin")
178		if err != nil {
179			t.Fatalf("replay under intact twin failed: %v", err)
180		}
181		if len(reports) != 1 || reports[0].Version.ID != "twin" ||
182			len(reports[0].Findings) != 1 || reports[0].Findings[0].Kind != "displacement" {
183			t.Fatalf("replay under twin misjudged: %+v", reports)
184		}
185	
186		// A plain replay selects the enabled version; with intact twin enabled
187		// the corrupt sibling never interferes.
188		if _, err := EnableVersion(dir, "twin"); err != nil {
189			t.Fatalf("EnableVersion: %v", err)
190		}
191		input2 := cmpBlockLine("1", "0xnew2", 9,
192			cmpSwap("0xn3", "p1", "w", 40, 0),
193			cmpSwap("0xn4", "p1", "u", 10, 1),
194		)
195		reports, err = Replay(strings.NewReader(input2), dir)
196		if err != nil {
197			t.Fatalf("replay under enabled twin failed: %v", err)
198		}
199		if len(reports) != 1 || reports[0].Version.ID != "twin" {
200			t.Fatalf("plain replay did not use the enabled version: %+v", reports)
201		}
202	}
203	
204	// TestReplayCorruptSiblingPreservedVerbatim proves a successful replay
205	// under an intact version neither repairs nor drops a corrupt sibling: the
206	// stored versions section, the enabled marker and every prior record come
207	// through byte for byte, and the run only appends its new record.
208	func TestReplayCorruptSiblingPreservedVerbatim(t *testing.T) {
209		dir := setupCorruptCompareArchive(t)
210		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
211			storedRule(t, ver, "displacement")["multiplier"] = 0
212		})
213		// Records are compared semantically: the corruption helper re-marshals
214		// the whole file with map key order, the replay write uses struct field
215		// order, and both are the same content. The versions section, by
216		// contrast, must survive byte for byte.
217		type archiveSkeleton struct {
218			Records        []record          `json:"records"`
219			Versions       []json.RawMessage `json:"versions"`
220			EnabledVersion string            `json:"enabledVersion"`
221		}
222		skeleton := func() archiveSkeleton {
223			var s archiveSkeleton
224			if err := json.Unmarshal(readArchiveFile(t, dir), &s); err != nil {
225				t.Fatal(err)
226			}
227			return s
228		}
229		before := skeleton()
230	
231		if _, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "twin"); err != nil {
232			t.Fatalf("replay under intact twin failed: %v", err)
233		}
234	
235		after := skeleton()
236		if !reflect.DeepEqual(before.Versions, after.Versions) {
237			t.Fatalf("stored versions rewritten:\nbefore=%s\nafter =%s", before.Versions, after.Versions)
238		}
239		if before.EnabledVersion != after.EnabledVersion {
240			t.Fatalf("enabled marker changed: %q -> %q", before.EnabledVersion, after.EnabledVersion)
241		}
242		if !reflect.DeepEqual(before.Records, after.Records[:len(before.Records)]) {
243			t.Fatalf("existing records changed")
244		}
245		if len(after.Records) != len(before.Records)+1 {
246			t.Fatalf("records = %d, want exactly one appended", len(after.Records))
247		}
248	}
249	
250	// TestReplayCorruptVersionPreservesArchive builds an archive holding every
251	// kind of state — reports, registered versions, the enabled marker, a
252	// suppression, alert processing records and manual review history — then
253	// proves a refused replay leaves the file byte-identical: the refusal
254	// never completes missing fields or fixes bad values in passing.
255	func TestReplayCorruptVersionPreservesArchive(t *testing.T) {
256		dir := t.TempDir()
257		register(t, dir, candidateVersionSpec)
258		if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); err != nil {
259			t.Fatal(err)
260		}
261		if _, err := EnableVersion(dir, "candC"); err != nil {
262			t.Fatal(err)
263		}
264		if _, _, err := RegisterSuppression(dir, []byte(
265			`{"id":"s1","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":1,"endHeight":100,"reason":"r"}`,
266		)); err != nil {
267			t.Fatal(err)
268		}
269		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
270			t.Fatal(err)
271		}
272		if _, err := SubmitReview(dir, ReviewSubmission{
273			ChainID: "1", BlockHash: "0xa", TxHash: "0xvictim", Kind: "displacement",
274			SubmissionID: "rev-1", Operator: "alice", Reason: "looks fine",
275			Status: ReviewStatusFalsePositive, ExpectedVersion: 0,
276		}); err != nil {
277			t.Fatal(err)
278		}
279	
280		// Damage the enabled version after all state exists: the displacement
281		// multiplier vanishes from the stored document.
282		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
283			delete(storedRule(t, ver, "displacement"), "multiplier")
284		})
285		before := readArchiveFile(t, dir)
286	
287		// Both selection paths refuse: the enabled version implicitly...
288		if _, err := Replay(strings.NewReader(replayCorruptInput), dir); !errors.Is(err, ErrCorruptVersion) {
289			t.Fatalf("enabled-version replay error = %v, want ErrCorruptVersion", err)
290		}
291		// ...and the same version named explicitly.
292		if _, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
293			t.Fatalf("explicit-version replay error = %v, want ErrCorruptVersion", err)
294		}
295	
296		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
297			t.Fatalf("refused replays changed the archive:\nbefore=%s\nafter =%s", before, after)
298		}
299	
300		// Every piece of prior state is still queryable and unchanged.
301		report, err := Query(dir, "1", "0xa")
302		if err != nil {
303			t.Fatal(err)
304		}
305		if report.Version.ID != "candC" || len(report.Findings) != 1 ||
306			report.Findings[0].Kind != "displacement" || report.Findings[0].Severity != 4 {
307			t.Fatalf("archived report changed: %+v", report)
308		}
309		history, err := ReviewHistoryQuery(dir, "1", "0xa", "0xvictim", "displacement")
310		if err != nil {
311			t.Fatal(err)
312		}
313		if history.Status != ReviewStatusFalsePositive || history.Version != 1 {
314			t.Fatalf("review history changed: %+v", history)
315		}
316		alerts, err := AlertHistory(dir, "1", "ops", 0, 100)
317		if err != nil {
318			t.Fatal(err)
319		}
320		if len(alerts) != 1 || alerts[0].Status != AlertStatusSuppressed {
321			t.Fatalf("alert records changed: %+v", alerts)
322		}
323	}
324	
325	// TestReplayCorruptVersionMultiplierZeroNoCrash pins the original crash:
326	// displacement enabled with the stored multiplier decayed to zero divided
327	// by zero as soon as one pool held two adjacent swaps. The replay must now
328	// fail cleanly with ErrCorruptVersion before detection ever runs.
329	func TestReplayCorruptVersionMultiplierZeroNoCrash(t *testing.T) {
330		dir := setupCorruptCompareArchive(t)
331		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
332			storedRule(t, ver, "displacement")["multiplier"] = 0
333		})
334		// candC's displacement rule is enabled; the input holds two adjacent
335		// same-pool swaps, the exact crash trigger.
336		_, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC")
337		if !errors.Is(err, ErrCorruptVersion) {
